<?php
require 'includes/bootstrap.php'; require_admin(); require 'includes/layout.php';
$view=$_GET['view']??'customers';if(!in_array($view,['customers','collaborators'],true))$view='customers';
if($_SERVER['REQUEST_METHOD']==='POST'&&$view==='collaborators'){
 verify_csrf();$uid=(string)($_POST['user_id']??'');$status=(string)($_POST['status']??'');
 if($uid!==''&&in_array($status,['draft','submitted','approved','rejected','suspended'],true)){db()->prepare('UPDATE partner_profiles SET status=?,reviewed_at=NOW(),reviewed_by=? WHERE user_id=?')->execute([$status,admin()['id'],$uid]);flash('success','Collaborator review updated.');}
 redirect('users.php?view=collaborators');
}
if($view==='customers'){$rows=db()->query("SELECT u.*,COUNT(r.id) reservation_count FROM users u LEFT JOIN reservations r ON r.customer_user_id=u.id WHERE u.role='customer' GROUP BY u.id ORDER BY u.created_at DESC")->fetchAll();}
else{$rows=db()->query("SELECT u.*,p.status partner_status,p.submitted_at,p.profile_json,COUNT(r.id) job_count FROM users u LEFT JOIN partner_profiles p ON p.user_id=u.id LEFT JOIN reservations r ON r.partner_user_id=u.id WHERE u.role='partner' OR u.partner_intent=1 GROUP BY u.id,p.status,p.submitted_at,p.profile_json ORDER BY u.created_at DESC")->fetchAll();}
page_header('Customers & collaborators'); ?>
<div class="filters people-tabs"><a class="<?=$view==='customers'?'active':''?>" href="?view=customers">Customers</a><a class="<?=$view==='collaborators'?'active':''?>" href="?view=collaborators">Collaborators</a></div><section class="panel"><div class="panel-head"><div><p class="eyebrow">DIRECTORY</p><h3><?=count($rows)?> <?=e($view)?></h3></div></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Contact</th><th>Role</th><th><?=$view==='customers'?'Requests':'Jobs / review'?></th><th>Joined</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><strong><?=e(trim($row['first_name'].' '.$row['last_name']))?></strong><small><?=e(substr($row['id'],0,14))?></small></td><td><?=e($row['email']?:'—')?><small><?=e($row['phone']?:'')?></small></td><td><?=e($row['role'])?><small><?=$row['verified_at']?'Verified':'Not verified'?></small></td><td><?php if($view==='customers'):?><?=(int)$row['reservation_count']?><?php else:?><form method="post" class="status-form"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="user_id" value="<?=e($row['id'])?>"><select name="status" onchange="this.form.submit()"><?php foreach(['draft','submitted','approved','rejected','suspended'] as $s):?><option value="<?=$s?>" <?=($row['partner_status']??'draft')===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select><small><?=(int)$row['job_count']?> assigned jobs</small></form><?php endif;?></td><td><?=e(date('M j, Y',strtotime($row['created_at'])))?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="empty">No records found.</td></tr><?php endif;?></tbody></table></div></section>
<?php page_footer();
